require "fpm/package"
require "backports/latest"

# Empty Package type. For strict/meta/virtual package creation

class FPM::Package::Empty < FPM::Package
  private

  def initialize(*args)
    super(*args)
    # Empty packages have no files, so default the architecture to "all"
    @architecture = "all"
  end

  public

  def output(output_path)
    logger.warn("Your package has gone into the void.")
  end
  def to_s(fmt)
    return ""
  end

  def validate(command)
    @messages = []

